from pathlib import Path
p=Path(__file__).resolve().parents[1]/'js'/'app.js'; s=p.read_text(encoding='utf-8')
s=s.replace("isCorrect=(q,a)=>JSON.stringify(norm(a))===JSON.stringify(norm(q.correctAnswer.length?q.correctAnswer:q.sourceAnswer));", "isCorrect=(q,a)=>q.matchingPairs?.length?q.matchingPairs.every((pair,i)=>String(a?.[i]||'').trim()===pair.value):JSON.stringify(norm(a))===JSON.stringify(norm(q.correctAnswer.length?q.correctAnswer:q.sourceAnswer));")
start=s.index('function answerInput('); end=s.index('function learning(',start)
replacement=r'''function figures(q,answers=false){let imgs=answers?[...(q.sourceImages||[]),...(q.answerImages||[])]:q.sourceImages||[];return imgs.length?`<div class="figures">${imgs.map((src,i)=>`<figure><img src="${esc(src)}" alt="${answers?'Completed answer exhibit':'Question exhibit'} for AI-103 Bank Q${q.id}" loading="lazy"><figcaption>${answers&&i?'PDF answer exhibit':'PDF question exhibit'}</figcaption></figure>`).join('')}</div>`:''}
function answerInput(q,value,mode){if(q.type==='drag-drop'&&q.matchingPairs?.length){let values=Array.isArray(value)?value:[],chips=shuffle((q.dragCandidates?.length?q.dragCandidates:q.matchingPairs.map(x=>x.value)));return `<div class="drag-board"><p class="muted">Drag each choice to its matching target. Distractors are included. You can also tap a choice and then tap a target.</p><div class="drag-bank">${chips.map(v=>`<button type="button" class="drag-chip" draggable="true" data-value="${esc(v)}">${esc(v)}</button>`).join('')}</div><div class="drop-list">${q.matchingPairs.map((pair,i)=>`<div class="drop-row"><div class="drop-target-label">${esc(pair.target)}</div><button type="button" class="drop-zone" data-index="${i}">${esc(values[i]||'Drop answer here')}</button><input class="drop-answer" type="hidden" value="${esc(values[i]||'')}"></div>`).join('')}</div></div>`}if(q.options.length){let multi=q.type==='multiple',vals=Array.isArray(value)?value:[value],opts=q.options;if(state[mode].random&&!['yes-no-matrix','drag-drop','code-completion','dropdown-hotspot'].includes(q.type))opts=shuffle(opts);return `<div class="choices">${opts.map(o=>`<label class="choice"><input name="answer" type="${multi?'checkbox':'radio'}" value="${esc(o.id)}" ${vals.includes(o.id)?'checked':''}><b>${o.id}.</b> ${esc(o.text)}</label>`).join('')}</div>`}return `<p class="warning">This PDF item relies on an image/table. Use the original exhibit above and enter the requested selections.</p><textarea id="freeAnswer" placeholder="Enter answer selections">${esc(value||'')}</textarea>`}
function bindDrag(){let selected='';document.querySelectorAll('.drag-chip').forEach(chip=>{chip.ondragstart=e=>e.dataTransfer.setData('text/plain',chip.dataset.value);chip.onclick=()=>{selected=chip.dataset.value;document.querySelectorAll('.drag-chip').forEach(x=>x.classList.toggle('selected',x===chip))}});document.querySelectorAll('.drop-zone').forEach(zone=>{let put=v=>{if(!v)return;zone.textContent=v;zone.nextElementSibling.value=v;selected='';document.querySelectorAll('.drag-chip').forEach(x=>x.classList.remove('selected'))};zone.ondragover=e=>{e.preventDefault();zone.classList.add('over')};zone.ondragleave=()=>zone.classList.remove('over');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('over');put(e.dataTransfer.getData('text/plain'))};zone.onclick=()=>put(selected)})}
function getAnswer(q){if(q.type==='drag-drop'&&q.matchingPairs?.length)return [...document.querySelectorAll('.drop-answer')].map(x=>x.value);return q.options.length?[...document.querySelectorAll('[name=answer]:checked')].map(x=>x.value):($('#freeAnswer')?.value.trim()||'')}
'''
s=s[:start]+replacement+s[end:]
s=s.replace("<div class=\"source\">${esc(q.question)}</div>${answerInput", "<div class=\"source\">${esc(q.question)}</div>${figures(q,false)}${answerInput")
s=s.replace("${reveal?learning(q,s.answers[q.id],mode==='test'):''}", "${reveal?figures(q,true)+learning(q,s.answers[q.id],mode==='test'):''}")
s=s.replace("$('#home').onclick=home;$('#flag').onchange", "bindDrag();$('#home').onclick=home;$('#flag').onchange")
p.write_text(s,encoding='utf-8')
